-- 038_typical_menus.sql
-- GENERATED by scripts/typical_menus/build_038.py from supabase/data/typical/typical_menus.json - edit the JSON, then re-run the script.
--
-- Part of #103. Typical menus: for each type of restaurant, the dishes it usually serves and the ingredients
-- those dishes usually have. This is GENERATED data (allowed by our lecturer), not any restaurant's menu.
-- 15 menus, 79 dishes. Types too mixed for one honest menu keep only the food-type hint:
-- 기타, 기타 휴게음식점, 일반조리판매, 외국음식전문점(인도,태국등), 뷔페식, 과자점: too mixed for one honest typical menu (e.g. Indian curry and Vietnamese pho share one category). They keep only the food-type hint.
--
-- How it stays honest:
--   * dishes.typical marks every generated dish; the app labels the menu "Typical menu for <type>" and never
--     shows a typical dish as Safe to anyone with a diet or allergy (Ask first at best). No prices (0 = hidden).
--   * apply_typical_menus() only fills restaurants with NO dishes at all, so run it after the chain menus (037).
--   * As soon as a restaurant gets any real dish (menu photo approval, owner, chain), a trigger deletes its
--     typical dishes, so real and typical never mix.
-- After reviewing, run:  select * from public.apply_typical_menus();
-- Undo everything:      delete from public.dishes where typical;
-- Safe to re-run.

begin;

alter table public.dishes add column if not exists typical boolean not null default false;
create index if not exists dishes_typical_idx on public.dishes (restaurant_id) where typical;

-- Team-only source tables (RLS on, no policies): the app never reads them, only the copied dishes.
create table if not exists public.typical_menus (
  id text primary key,
  name_ko text not null,
  name_en text not null,
  categories text[] not null check (cardinality(categories) > 0)  -- restaurants.category values
);
create table if not exists public.typical_menu_dishes (
  menu_id text not null references public.typical_menus (id) on delete cascade,
  sort integer not null,
  name_ko text not null,
  name_en text not null,
  contains text[] not null default '{}',
  may_contain text[] not null default '{}',
  primary key (menu_id, sort)
);
alter table public.typical_menus enable row level security;
alter table public.typical_menu_dishes enable row level security;
revoke all on public.typical_menus, public.typical_menu_dishes from anon, authenticated;

-- Refill the source tables from the JSON (re-run safe).
delete from public.typical_menus;

-- Copies a typical menu to every restaurant of its type that has no dishes yet.
create or replace function public.apply_typical_menus()
returns table (menu_id text, restaurants_filled bigint, dishes_added bigint)
language plpgsql
set search_path = ''
as $$
begin
  return query
  with empty as (
    select r.id, r.category from public.restaurants r
    where not exists (select 1 from public.dishes d where d.restaurant_id = r.id)
  ), added as (
    select e.id || '-typical-' || m.id || '-' || lpad(td.sort::text, 2, '0'), e.id, td.name_ko, td.name_en,
           0, td.contains, td.may_contain, 0, null, true
    from empty e
    join public.typical_menus m on e.category = any (m.categories)
    join public.typical_menu_dishes td on td.menu_id = m.id
    on conflict (id) do nothing
    returning restaurant_id, id
  )
  select regexp_replace(split_part(a.id, '-typical-', 2), '-[0-9]+$', '') as menu_id,
         count(distinct a.restaurant_id), count(*)
  from added a group by 1 order by 1;
end;
$$;
revoke execute on function public.apply_typical_menus() from public, anon, authenticated;

-- A real dish replaces the typical menu: when a restaurant gets any non-typical dish, its typical dishes go.
create or replace function public.drop_typical_when_real()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.dishes where restaurant_id = new.restaurant_id and typical;
  return null;
end;
$$;
revoke execute on function public.drop_typical_when_real() from public, anon, authenticated;
drop trigger if exists dishes_drop_typical_when_real on public.dishes;
create trigger dishes_drop_typical_when_real
  after insert on public.dishes
  for each row when (not new.typical)
  execute function public.drop_typical_when_real();

commit;

